Subroutine doble(x As Integer) As Integer
  Return x * 2;
EndSubroutine
Subroutine aplicar(f As Subroutine(Integer) As Integer, valor As Integer) As Integer
  Return f(valor);
EndSubroutine
Algorithm Aplicar
  Define operacion As Subroutine(Integer) As Integer <- doble;
  Write operacion(4), " ", aplicar(doble, 10);
EndAlgorithm

Subroutine multiplicador(factor As Integer) As Subroutine(Integer) As Integer
  Return Subroutine(x As Integer) As Integer
    Return x * factor;
  EndSubroutine;
EndSubroutine
Algorithm Clausuras
  Define doble As Subroutine(Integer) As Integer <- multiplicador(2);
  Define triple As Subroutine(Integer) As Integer <- multiplicador(3);
  Write doble(5), " ", triple(5);
EndAlgorithm

Algorithm CapturaMutable
  Define n As Integer <- 1;
  Define f As Subroutine() As Integer <- Subroutine() As Integer
    Return n;
  EndSubroutine;
  n <- 2;
  Write f();
EndAlgorithm
